import { WieWeb, extractArchiveResources } from "@pkg";

import type { PlayerSession, SessionEvent } from "../backend";
import { presentFrame } from "../display";
import { AudioPlayer } from "../midi";
import { rustPanic } from "../panic";
import type { EmulatorHost } from "./tauri-host";

export interface WasmSession extends PlayerSession {
  suspend(suspended: boolean): void;
}

export const startWasmSession = (
  filename: string,
  archive: Uint8Array,
  font: Uint8Array,
  onEvent: (event: SessionEvent) => void,
  host?: EmulatorHost,
  suspended = false,
): WasmSession => {
  if (rustPanic) throw rustPanic;
  const canvas = document.getElementById("canvas") as HTMLCanvasElement;
  canvas.width = 240;
  canvas.height = 320;
  const audio = host?.audio ?? new AudioPlayer();
  let emulator: WieWeb;
  try {
    emulator = new WieWeb(filename, archive, canvas, font, audio, host);
  } catch (error) {
    audio.dispose();
    throw rustPanic ?? error;
  }
  const keys = new Set<string>();
  let running = true;
  let preparing = true;
  let frame: number;
  let presented = -1;
  /** The guest is not run before this time (performance.now()). */
  let holdUntil = 0;

  const session: WasmSession = {
    readResources(prefixes) {
      return running ? extractArchiveResources(archive, prefixes) : new Map();
    },
    async key(key, pressed) {
      if (!running || preparing || suspended) return;
      if (pressed && !keys.has(key)) {
        emulator.key_down(key);
        keys.add(key);
      } else if (!pressed && keys.delete(key)) {
        emulator.key_up(key);
      }
    },
    hold(ms) {
      holdUntil = Math.max(holdUntil, performance.now() + ms);
    },
    async releaseKeys() {
      if (!running) return;
      for (const key of keys) emulator.key_up(key);
      keys.clear();
    },
    suspend(paused) {
      if (!running) return;
      suspended = paused;
      for (const key of keys) emulator.key_up(key);
      keys.clear();
      cancelAnimationFrame(frame);
      onEvent({ type: "suspended", suspended });
      if (!suspended) frame = requestAnimationFrame(update);
    },
    cheats: {
      memorySize() {
        if (!running) return 0;
        return emulator.cheat_memory_size();
      },
      memoryRanges() {
        if (!running) return new Uint32Array();
        return emulator.cheat_memory_ranges();
      },
      dump(address, size) {
        if (!running) return new Uint8Array();
        return emulator.cheat_dump(address >>> 0, size >>> 0);
      },
      writeBytes(address, data) {
        if (!running) return;
        emulator.cheat_write_bytes(address >>> 0, data);
      },
      search(value, width, bigEndian, previous) {
        if (!running) return new Uint32Array();
        return emulator.cheat_search(value >>> 0, width, bigEndian, previous ?? new Uint32Array());
      },
      read(address, width, bigEndian) {
        if (!running) return 0;
        return emulator.cheat_read(address >>> 0, width, bigEndian);
      },
      write(address, width, bigEndian, value) {
        if (!running) return;
        emulator.cheat_write(address >>> 0, width, bigEndian, value >>> 0);
      },
      freeze(address, width, bigEndian, value) {
        if (!running) return;
        emulator.cheat_freeze(address >>> 0, width, bigEndian, value >>> 0);
      },
      unfreeze(address) {
        if (!running) return;
        emulator.cheat_unfreeze(address >>> 0);
      },
      clearFreezes() {
        if (!running) return;
        emulator.cheat_clear_freezes();
      },
    },
    async stop() {
      if (!running) return;
      running = false;
      cancelAnimationFrame(frame);
      // Aborting panics do not unwind Rust borrows; only JavaScript resources can be released.
      if (rustPanic) audio.dispose();
      else emulator.free();
      onEvent({ type: "stopped", failed: false });
    },
  };

  const update = () => {
    if (!running || suspended) return;
    if (performance.now() < holdUntil) {
      frame = requestAnimationFrame(update);
      return;
    }
    try {
      emulator.update();
      const painted = emulator.frame_count();
      if (painted !== presented) {
        presented = painted;
        presentFrame();
        onEvent({ type: "frame" });
      }
      if (emulator.is_exited()) {
        void session.stop();
        return;
      }
      if (preparing && !emulator.is_preparing()) {
        preparing = false;
        onEvent({ type: "ready" });
      }
      frame = requestAnimationFrame(update);
    } catch (error) {
      const cause = rustPanic ?? error;
      onEvent({ type: "error", message: String(cause), cause });
    }
  };
  onEvent({ type: "suspended", suspended });
  if (!suspended) frame = requestAnimationFrame(() => { frame = requestAnimationFrame(update); });
  return session;
};
